import json

doc = {
  "recipe": {
    "name": "Sourdough",
    "flour": {"type": "Rye", "grams": 500},
    "water": {"ml": 350, "tempC": 22},
    "salt": {"grams": 10, "added": True}
  }
}

def fmt(v):
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        return f"{v:.1f}"
    return str(v)

def walk(node, prefix):
    for k, v in node.items():
        path = f"{prefix}.{k}" if prefix else k
        if isinstance(v, dict):
            walk(v, path)
        else:
            print(f"{path} = {fmt(v)}")

walk(doc, "")

import json

doc = {
  "plots": [
    {"plot": "P1", "readings": {"moisture": 45, "ph": 6.5, "fertilized": True}},
    {"plot": "P2", "readings": {"moisture": 30, "ph": 7.2, "fertilized": False}},
    {"plot": "P3", "readings": {"moisture": 55, "ph": 6.8, "fertilized": True}}
  ]
}

def type_name(v):
    if isinstance(v, bool):
        return "Bool"
    if isinstance(v, int):
        return "Int"
    if isinstance(v, float):
        return "Real"
    return "Text"

count = 0
for p in doc["plots"]:
    r = p["readings"]
    print(f"{p['plot']}: moisture={type_name(r['moisture'])}, ph={type_name(r['ph'])}, fertilized={type_name(r['fertilized'])}")
    if r["fertilized"]:
        count += 1

print(f"Fertilized plots: {count}")

