import json

data = json.loads('''[
  {"time": "06:00", "temp": 12.4, "humidity": 88, "windy": false},
  {"time": "12:00", "temp": 21.7, "humidity": 55, "windy": true},
  {"time": "18:00", "temp": 17.2, "humidity": 63, "windy": false}
]''')

def type_name(v):
    if isinstance(v, bool):
        return "Bool"
    if isinstance(v, int):
        return "Int"
    if isinstance(v, float):
        return "Real"
    if isinstance(v, str):
        return "Str"
    return type(v).__name__

for obs in data:
    parts = [obs["time"]]
    for key in ("temp", "humidity", "windy"):
        parts.append(f"{key}:{type_name(obs[key])}")
    print(" ".join(parts))

import json

data = {
  "players": [
    {"name": "Ana", "score": 142, "bonus": 3.5},
    {"name": "Bo", "score": 98, "bonus": 0.0},
    {"name": "Cy", "score": 175, "bonus": 7.25}
  ]
}

players = data["players"]
for p in players:
    p["total"] = p["score"] + p["bonus"]

players.sort(key=lambda p: p["total"], reverse=True)

print(f"{'Rank':<4}  {'Name':<4}  {'Total':>6}")
for i, p in enumerate(players, 1):
    print(f"{i:<4}  {p['name']:<4}  {p['total']:>6.2f}")

menu = [
    "Grilled chicken with rice",
    "Tomato soup and bread",
    "Chicken salad wrap",
    "Rice pudding for dessert",
    "Tomato pasta with cheese",
    "Grilled fish with potatoes",
    "Chicken curry over rice",
    "Tomato sauce on noodles",
    "Rice and beans bowl",
    "Grilled vegetables with rice",
]

targets = ["Chicken", "Tomato", "Rice"]

index = {t: [] for t in targets}
for i, line in enumerate(menu, start=1):
    for t in targets:
        if t.lower() in line.lower():
            index[t].append(i)

for t in targets:
    print(f"{t}: {' '.join(str(n) for n in index[t])}")
